// First integrated oscilloscope top-level.
//
// This version uses clk as the common system and parallel-transfer clock. The
// transmitter gates DATA_CLK while it is active. A later revision can replace
// this with a divided or PLL-generated bus clock and add an asynchronous FIFO.
//
// The generated MAX 10 Modular ADC Core IP is connected through the ADC command
// and response ports below. The IP itself is normally generated by Quartus.

module oscilloscope_top #(
    parameter int ADC_WIDTH  = 12,
    parameter int ADDR_WIDTH = 11
) (
    input  logic                    clk,
    input  logic                    rst,

    // SPI configuration bus.
    input  logic                    spi_sclk,
    input  logic                    spi_cs_n,
    input  logic                    spi_mosi,
    output logic                    spi_miso,

    // ESP32 parallel data bus.
    output logic [ADC_WIDTH-1:0]    data,
    output logic                    data_clk,
    output logic                    data_valid,
    input  logic                    data_ready,
	 
    // Status outputs useful during initial FPGA bring-up.
    output logic                    status_busy,
    output logic                    status_triggered,
    output logic                    status_done
);

    // Arduino A0 is the first externally connected analog channel.
    localparam logic [4:0] ADC_CHANNEL = 5'd1;

    logic [ADC_WIDTH-1:0] trigger_level;
    logic                  trigger_enable;
    logic                  trigger_rising;
    logic [31:0]           pretrigger_count_cfg;
    logic [31:0]           posttrigger_count_cfg;
    logic [31:0]           sample_rate_cfg;
    logic                  arm_pulse;
    logic                  abort_pulse;
    logic                  clear_pulse;

    logic [ADDR_WIDTH:0]   capture_length_raw;
    logic [31:0]           capture_length;
    logic [ADDR_WIDTH:0]   capture_read_index;
    logic [ADDR_WIDTH-1:0] capture_read_addr;
    logic [ADC_WIDTH-1:0]  capture_read_data;
    logic                  capture_read_valid;

    logic                  adc_sample_valid;
    logic [ADC_WIDTH-1:0]  adc_sample_data;
    logic [4:0]            adc_sample_channel;

    logic                  adc_command_valid;
    logic [4:0]            adc_command_channel;
    logic                  adc_command_startofpacket;
    logic                  adc_command_endofpacket;
    logic                  adc_command_ready;
    logic                  adc_response_valid;
    logic [4:0]            adc_response_channel;
    logic [ADC_WIDTH-1:0]  adc_response_data;
    logic                  adc_response_startofpacket;
    logic                  adc_response_endofpacket;

    logic                  data_ready_meta;
    logic                  data_ready_sync;
    logic                  capture_done_delayed;
    logic                  transmitter_start;
    logic                  transmitter_busy;
    logic                  transmitter_done;
	 
	 logic                    adc_pll_locked;
	 logic                    adc_pll_clock;



    assign capture_length = {{(31-ADDR_WIDTH){1'b0}}, capture_length_raw};
    assign capture_read_index = {1'b0, capture_read_addr};
	 
	 localparam int BUS_CLOCK_DIVISOR = 250;

	 logic [31:0] bus_clock_counter;
	 logic        slow_bus_clk;

	 always_ff @(posedge clk or posedge rst) begin
	 	  if (rst) begin
			   bus_clock_counter <= 32'd0;
			   slow_bus_clk      <= 1'b0;
		  end else if (bus_clock_counter == BUS_CLOCK_DIVISOR - 1) begin
			   bus_clock_counter <= 32'd0;
			   slow_bus_clk      <= ~slow_bus_clk;
		  end else begin
			   bus_clock_counter <= bus_clock_counter + 1'b1;
		  end
	 end

    // Generated Platform Designer ADC system. The .qip generated by
    // Platform Designer must be added to the Quartus project.
    osc_adc_system adc_system (
        .clk_clk                               (clk),
        .modular_adc_0_adc_pll_clock_clk       (adc_pll_clock),
        .modular_adc_0_adc_pll_locked_export   (adc_pll_locked),
        .modular_adc_0_clock_clk               (clk),
        .modular_adc_0_command_valid           (adc_command_valid),
        .modular_adc_0_command_channel         (adc_command_channel),
        .modular_adc_0_command_startofpacket   (adc_command_startofpacket),
        .modular_adc_0_command_endofpacket     (adc_command_endofpacket),
        .modular_adc_0_command_ready           (adc_command_ready),
        .modular_adc_0_reset_sink_reset_n      (~rst),
        .modular_adc_0_response_valid          (adc_response_valid),
        .modular_adc_0_response_channel        (adc_response_channel),
        .modular_adc_0_response_data           (adc_response_data),
        .modular_adc_0_response_startofpacket  (adc_response_startofpacket),
        .modular_adc_0_response_endofpacket    (adc_response_endofpacket),
        .reset_reset_n                         (~rst)
    );

    // Synchronize the ESP32's DATA_READY signal into the FPGA clock domain.
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            data_ready_meta  <= 1'b0;
            data_ready_sync  <= 1'b0;
            capture_done_delayed <= 1'b0;
        end else begin
            data_ready_meta  <= data_ready;
            data_ready_sync  <= data_ready_meta;
            capture_done_delayed <= status_done;
        end
    end

    // Generate one transmitter-start pulse when a capture first completes.
    assign transmitter_start = status_done;

    spi_control_bridge #(
        .ADC_WIDTH   (ADC_WIDTH),
        .COUNT_WIDTH (32)
    ) control_bridge (
        .rst                    (rst),
        .clk                    (clk),
        .spi_sclk               (spi_sclk),
        .spi_cs_n               (spi_cs_n),
        .spi_mosi               (spi_mosi),
        .spi_miso               (spi_miso),
        .trigger_level          (trigger_level),
        .trigger_enable         (trigger_enable),
        .trigger_rising         (trigger_rising),
        .pretrigger_count       (pretrigger_count_cfg),
        .posttrigger_count      (posttrigger_count_cfg),
        .sample_rate            (sample_rate_cfg),
        .arm_pulse              (arm_pulse),
        .abort_pulse            (abort_pulse),
        .clear_pulse            (clear_pulse),
        .status_busy            (status_busy),
        .status_triggered       (status_triggered),
        .status_done            (status_done),
        .status_capture_length (capture_length)
    );

    max10_adc_interface #(
        .ADC_WIDTH     (ADC_WIDTH),
        .CHANNEL_WIDTH (5)
    ) adc_interface (
        .clk                         (clk),
        .rst                         (rst),
        .enable                      (1'b1),
        .channel_select              (ADC_CHANNEL),
        .adc_pll_locked              (adc_pll_locked),
        .adc_command_valid           (adc_command_valid),
        .adc_command_channel         (adc_command_channel),
        .adc_command_startofpacket  (adc_command_startofpacket),
        .adc_command_endofpacket    (adc_command_endofpacket),
        .adc_command_ready           (adc_command_ready),
        .adc_response_valid          (adc_response_valid),
        .adc_response_channel        (adc_response_channel),
        .adc_response_data           (adc_response_data),
        .adc_response_startofpacket (adc_response_startofpacket),
        .adc_response_endofpacket   (adc_response_endofpacket),
        .sample_valid                (adc_sample_valid),
        .sample_data                 (adc_sample_data),
		  .sample_rate_hz(sample_rate_cfg),
        .sample_channel              (adc_sample_channel)
    );

    osc_capture #(
        .SAMPLE_WIDTH (ADC_WIDTH),
        .ADDR_WIDTH   (ADDR_WIDTH)
    ) capture_engine (
        .clk                (clk),
        .rst                (rst),
        .sample_data        (adc_sample_data),
        .sample_valid       (adc_sample_valid),
        .arm                (arm_pulse),
        .abort              (abort_pulse),
        .trigger_enable     (trigger_enable),
        .trigger_rising     (trigger_rising),
        .trigger_level      (trigger_level),
        .pretrigger_count   (pretrigger_count_cfg[ADDR_WIDTH:0]),
        .posttrigger_count  (posttrigger_count_cfg[ADDR_WIDTH:0]),
        .busy               (status_busy),
        .triggered          (status_triggered),
        .done               (status_done),
        .capture_length     (capture_length_raw),
        .read_index         (capture_read_index),
        .read_data          (capture_read_data),
        .read_valid         (capture_read_valid)
    );

    parallel_sample_tx #(
        .SAMPLE_WIDTH (ADC_WIDTH),
        .ADDR_WIDTH   (ADDR_WIDTH)
    ) sample_transmitter (
        .rst                (rst),
        .bus_clk            (slow_bus_clk),
        .start              (transmitter_start),
        .sample_count       (capture_length[ADDR_WIDTH:0]),
        .data_ready         (data_ready_sync),
        .sample_rd_addr     (capture_read_addr),
        .sample_rd_data     (capture_read_data),
        .data               (data),
        .data_clk           (data_clk),
        .data_valid         (data_valid),
        .busy               (transmitter_busy),
        .done               (transmitter_done)
    );
	 
	 adc_pll adc_pll_inst(
		.inclk0(clk),
		.areset(rst),
		.c0(adc_pll_clock),
		.locked(adc_pll_locked)
	 );	

endmodule
